result=dict(schema='V161_ROOT_PUBLIC_TRAIN_COUNTERFACTUAL_INPUT_PROOF_COMPLETE_UNSOLVED',completed=True,UTC=datetime.datetime.now(datetime.timezone.utc).isoformat(),execution_and_integrity_PASS=True,all159_pixel_proofs_PASS=False,attempted_pairs=159,passed_pairs=157,retained_failed_pairs=2,constructed_variant_records=477,variant_records_are_not_independent_real_photos=True,original_anchor_queries=53,original_anchor_frames=46,fixed_TRAIN_donors=59,all8_input_occurrences=3816,all8_original_inputU=360,feature_extraction_calls=0,model_training_updates=0,primary_visibility_accuracy_not_measured_here=True,new_native_visibility_and_quality_all_UNKNOWN=True,new_owner_labels_or_training_admission=False,conditional_eligibility=dict(pairs=157,variant_rows=471,additional_COVER_SHAM_rows_if_later_admitted=314,BEFORE_not_duplicated_in_prospective_owner_loss=True),native_coverage=s['native_coverage'],missing_anchor_native_slots=[2,3],actual_donor_execution=bind(V/'ROOT_ACTUAL_DONOR_PROOF_EXECUTION.json'),actual_pixel_execution=bind(V/'ROOT_ACTUAL_SOURCE_PIXEL_COMPLETED.json'),summary=bind(V/'derived_summary/SUMMARY.json'),independent_review=bind(V/'independent_pixel_review/REVIEW_COMPLETE.json'),fixed12_visual_readout=bind(V/'fixed12_visual_preparation/READOUT_COMPLETE.json'),first_fixed_example=bind(first),feature_input_metadata=bind(V/'next_feature_input_metadata/METADATA_COMPLETE.json'),next_requirements=bind(V/'ROOT_NEXT_FEATURE_AND_CONTROL_REQUIREMENTS.json'),interpretation_KO=['같은 q/L의 원본·직접덮기·옆배치를 실제 만들었고 변경 fullRGB와 모든 문맥/local/중앙 입력이 일관됨을 검증했다.','157개가 모든 대조 조건을 통과했다. 실패2개는 옆 가림물이 selected RGB96에 들어오지 않아 대조 조건이 부족했으며, 이동/교체/재시도 없이 보존했다.','주 native 가림·좌표품질 정답은 모두 UNKNOWN이다. 이 결과는 중심 표면 보조 학습의 입력 준비이며 주 가림 학습/성능 성공이 아니다.','원래 전체 WOOD/SQUARE/native8 과제는 유지한다. 공개 anchor에는 native2/3이 없고 같은53 query/46frame를 재사용하므로477개를 독립 실사로 세지 않는다.'],selected_model=None,adopted=False,fully_solved=False,goal_status='active_unsolved',current223_reads=0,V112_reads=0,PnP_q_L_changes=0)
